function obtenerFechaActual(){
	var f = new Date();
	var dia = f.getDate()
	if (dia < 10) {
		dia = "0" + dia;
	}
	var mes = f.getMonth() + 1
	if (mes < 10) {
		mes = "0" + mes;
	}
	return f.getFullYear() + "-" + mes + "-" + dia;
}
