	datos.append("codBarras", codBarras)
	datos.append("tipoproducto", tipoproducto)
	datos.append("CodProveedorFK", CodProveedorFK)
	datos.append("cod_local", cod_localFKUSer)
	datos.append("codFabricaFK", codFabricaFK)
