function LimpiarCamposNroFactura(){
	document.getElementById("inptNroFactura").value="";		 
var f = new Date();
	var dia =f.getDate()
	if(dia<10){
		dia="0"+dia;
	}
	var mes =f.getMonth()+1
	if(mes<10){
		mes="0"+mes;
	}
	var hora =f.getHours()
	if(hora<10){
		hora="0"+hora;
	}
	var min =f.getMinutes()
	if(min<10){
		min="0"+min;
	}
	 	document.getElementById('inptFechaNroFactura').value=f.getFullYear()+"-"+mes+"-"+dia;
	

	idAbmNroFactura="";

}
